UPDATE companies SET description='Evotronics Inc is a family-owned PCB contract manufacturing service company based in Minneapolis, Minnesota. Founded in 1995 by Tam Tran, the business is now led by co-owners Anh Tran and Ken Nguyen. The company began as a provider of design, manufacture, test, distribution, and return/repair services for electronic components and assemblies to original equipment manufacturers.

The shop specializes in printed circuit board assembly, offering through-hole, surface-mount, and mixed-technology builds, along with custom cable assembly, electro-mechanical integration, and full box-build services including decals, serialization, and labeling. Its facility is climate-controlled and monitored by a surveillance system. Capabilities extend to automated axial insertion (ammo pack and cut tape), semi-automatic radial preparation, hand placement for odd-shaped components, conformal coating (UV, epoxy), in-line wash, and rework or engineering modifications after completion. The company emphasizes quick-turn prototypes and small-to-medium production runs, with the ability to scale to higher volumes.

Evotronics serves OEMs across retail, consumer, industrial, medical, and defense/aerospace sectors. Customers rely on the firm for first-article testing, design-for-manufacturing feedback, bill-of-materials alternative sourcing, and a no-stencil solder-paste process that accelerates prototype starts.

The company highlights its ESD-safe environment (third-party audited), UL certification, ISO 9001:2015 registration, and FDA registration as pillars of its quality system, alongside an RF enclosure room for specialized testing.', certifications=ARRAY['ISO 9001:2015','UL Certified (Underwriters Laboratories Inc.)','FDA Registered']::text[], profile='{"capabilities": ["PCB prototyping", "Through-hole assembly", "Surface mount assembly", "Custom cable assembly", "Rework and repair services", "Engineering service to customer''s design", "Hand placement for odd-shaped components", "Flood box in-line wash", "Conformal coating (UV, epoxy)", "Electro-mechanical assembly", "Full box-build (decals, serialization, labeling)", "Automated axial insertion (ammo pack, cut tape)", "Semi-automatic axial/radial prep", "Design for manufacturing (DFM) support", "BOM alternative component sourcing", "Wire soldering on PCB", "Engineering modifications post-completion", "Re-labeling and packaging", "First article testing", "In-circuit testing capability", "RF enclosure room testing"], "industries": ["Retail", "Consumer", "Industrial", "Medical", "Defense", "Aerospace"], "materials": ["Solder paste", "UV adhesive", "Epoxy", "Conformal coating"], "equipment": ["Automated Axial Machine (ammo pack, cut tape)", "KIC Profiler", "Flood Box for In-Line Wash", "Brady Label Maker", "RF Enclosure Room", "Semi-Automatic Axial/Radial Prep Machines", "Manual Axial/Radial Prep Machines"], "volume": "Small production runs to higher volume production", "lead_time": "", "tolerances": "", "built_on": ["No-stencil solder paste printing for rapid prototype starts", "Quick-turn prototype and first-article service", "ESD-safe, third-party-audited environment", "Full box-build including decals, serialization, and labeling"], "facts_used": ["Founded 1995 by Tam Tran, family-owned, co-owners Anh Tran and Ken Nguyen -> /about", "Location Minneapolis, Minnesota -> /about, db", "ISO 9001:2015, UL Certified, FDA Registered, ESD Safe Environment -> /about", "Capabilities: PCB prototyping, thru-hole, surface mount, custom cable, rework, electro-mechanical, final assembly, conformal coating, automated axial insertion -> /services, /", "Industries: retail, consumer, industrial, medical, defense and aerospace -> /, /about", "Equipment: Automated Axial Machine, KIC Profiler, Flood Box, Brady Label Maker, RF Enclosure Room -> /services", "Facility: climate controlled, surveillance -> /about", "Volume: small production runs to higher volume -> /", "No stencil needed for solder paste -> /services", "Quick turnaround prototypes -> /", "Design for manufacturing, BOM alternative -> /services", "First article testing, in-testing capability -> /, /about", "Engineering service to customer''s design -> /services", "Hand placement capabilities -> /services", "Flood box capability -> /services", "Adhesive application (UV, epoxy, conformal coating) -> /services", "Full enclosure assembly -> /services", "Engineering modifications after completion -> /services", "Re-labeling and packaging -> /services"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We are the trusted Provider of printed circuit board (PCB) contract manufacturing services in the Minneapolis / St. Paul area", "founded_year": "1995", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='evotronics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Based in Milwaukee, Wisconsin, Excel Connection Inc. was founded in 1987. The company operates a 30,000-square-foot manufacturing facility with the potential to expand an additional 30,000 square feet as demand grows.

Excel Connection manufactures lead wires, wire harnesses, cable assemblies, ribbon cables, coaxial cables, fiber optics, power cables, heavy gauge cables up to 777 MCM, and electro-mechanical panels. Its capabilities include automated wire cutting, stripping, crimping, soldering (RoHS and lead-based per IPC/WHMA-A-620), wire marking, braiding, MIL-spec protective coatings, potting, ultrasonic splicing, panel box and DIN rail assembly, coil cord fabrication, and vendor-managed stocking programs. The facility houses automated wire processing machinery, induction soldering, HIPOT testing, and hydraulic equipment for heavy gauge cable processing.

The company serves customers nationwide and internationally, with explicit experience in alternative energy and medical manufacturing sectors. It handles projects ranging from high-volume simple lead wires to low-quantity complex harnesses.

Excel Connection emphasizes fast, on-time delivery, same-day service for stocked parts, and quality certifications including ISO 9001:2015 and IPC-620 certified personnel. Its vendor-managed stocking programs target 99% on-time delivery and reduced customer inventory costs.', certifications=ARRAY['ISO 9001:2015','RoHS']::text[], profile='{"capabilities": ["Cable assembly", "Wire harness assembly", "Lead wire assembly", "Electro-mechanical assembly", "Wire cutting (24 gauge to 777 MCM)", "Wire stripping", "Crimping (automated crimp monitoring presses, hydraulic crimpers)", "Soldering (RoHS and lead-based per IPC/WHMA-A-620)", "Wire marking (inkjet printing, Brady labels, heat shrink ID)", "Braiding / loom protective coverings", "MIL-spec protective coatings", "Potting / feed-through epoxy", "Ultrasonic splicing with dual wall adhesive heat shrink", "Panel box / DIN rail assembly (switches, relays, transformers, terminal blocks per UL)", "Coil cord and plug assemblies (custom cord sets, coil cords, power cords)", "Material and parts kitting", "Vendor-managed stocking programs", "Pull force testing and certification (up to 1000 lbs, HIPOT testing)", "Circuit testing on assembly boards", "Induction soldering", "Automated wire processing machinery (strips, terminates, solders)", "Prototyping services"], "industries": ["Alternative Energy", "Medical Manufacturing"], "materials": ["Heavy gauge cable up to 777 MCM", "Wire (24 gauge to 777 MCM)", "Ribbon cables", "Coaxial cables", "Fiber optics", "Power cables", "Lead wires"], "equipment": ["Automated wire processing machinery (strips, terminates, solders)", "Induction soldering equipment", "HIPOT testing equipment", "Braiding equipment", "Cable cutting and crimping tools (up to 777 MCM)", "15,000 lb and 6,000 lb forklifts", "Automated crimp monitoring presses", "Hydraulic crimpers", "Custom hydraulic equipment for heavy gauge cable"], "volume": "", "lead_time": "Same-day service available", "tolerances": "", "built_on": ["S