": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='extreme-metal-fabrication' AND approved AND profile IS NULL;
UPDATE companies SET description='F & P America Manufacturing Inc. operates from Troy, Ohio, where it was established in 1993 as a distribution and assembly facility. The company traces its roots to its Japanese parent, F-Tech, founded in 1947 in Saitama Prefecture as a metal toy maker. F-Tech began supplying motorcycle parts to Honda in 1959 and later became a tier-one automotive supplier. To support Honda’s North American operations, F-Tech opened a Canadian plant in 1986 and added the Ohio location as demand grew.

The Troy plant produces and assembles automotive components including pedal assemblies, front and rear subframes, and suspension parts. Core processes encompass progressive and traditional stamping of rolled steel, welding, hydroforming of steel tube, painting, and final assembly. The facility has doubled its building capacity twice, in 1996 and 2001, and today employs roughly 900 associates across 19 global locations under the F-Tech umbrella.

As a tier-one automotive systems supplier, F & P America serves major OEMs such as Honda, Toyota, and General Motors. Its parts are designed for direct installation on vehicle assembly lines, and the company also provides research and development support through F.tech R&D North America.

The company emphasizes a culture of quality and associate engagement, citing numerous awards for quality, delivery, safety, and community involvement. It holds IATF-16949 and ISO 14001 certifications and states that its workforce is central to delivering “unsurpassed quality.”', certifications=ARRAY['IATF-16949','ISO 14001']::text[], profile='{"capabilities": ["Research & Development", "Stamping", "Welding", "Hydroforming", "Painting", "Assembly"], "industries": ["Automotive"], "materials": ["Rolled steel", "Steel tube"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Tier-one supplier to Honda, Toyota, and General Motors", "IATF-16949 and ISO 14001 certified", "Approximately 900 associates across 19 global locations", "In-house R&D via F.tech R&D North America", "Integrated stamping, welding, hydroforming, painting, and assembly"], "facts_used": ["Established 1993 in Troy, Ohio -> /about", "Parent company F-Tech founded 1947 in Japan -> /about", "Honda relationship since 1959 -> /about", "North America expansion 1986 Canada plant -> /about", "Approximately 900 associates -> /about", "Clients: Honda, Toyota, General Motors -> /about", "Certifications: IATF-16949, ISO 14001 -> /about", "Capabilities: R&D, Stamping, Welding, Hydroforming, Painting, Assembly -> /capabilities", "Products: pedal assemblies, subframes, suspension parts -> /", "19 global locations -> /", "Doubled building capacity 1996 and 2001 -> /about", "Initial distribution and assembly facility -> /about", "Mass production for Honda 1994 -> /about", "Added stamping and hydroforming 1996 and 2001 -> /about", "Quality awards for delivery, safety, community -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We produce and assemble the highest quality parts for the automotive industry.", "founded_year": "1993", "employee_count": "approximately 900", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_link